import{At as e,Et as t,Ot as n,Zt as r,n as i,qt as a}from"./chunks/framework.C8R-a4p3.js";var o=JSON.parse(`{"title":"Agentic Coding — Directing Agent Teams","description":"How I use OpenCode, Codex, Claude Code and Hermes Agent to ship production software — the overview of my agentic workflow.","frontmatter":{"title":"Agentic Coding — Directing Agent Teams","description":"How I use OpenCode, Codex, Claude Code and Hermes Agent to ship production software — the overview of my agentic workflow."},"headers":[],"relativePath":"en/agentic/overview/index.md","filePath":"en/agentic/overview/index.md"}`),s={name:`en/agentic/overview/index.md`};function c(i,o,s,c,l,u){let d=r(`StepBar`);return a(),t(`div`,null,[o[0]||=n(`<h1 id="agentic-coding-—-directing-agent-teams" tabindex="-1">Agentic Coding — Directing Agent Teams <a class="header-anchor" href="#agentic-coding-—-directing-agent-teams" aria-label="Permalink to “Agentic Coding — Directing Agent Teams”">​</a></h1><p>Agentic coding is the practice of directing autonomous coding agents the way a tech lead directs a team: with clear specs, tight review loops and full accountability. It is my daily method for shipping software, and I consider it the single most important engineering skill I have built in the last three years.</p><p>My toolchain is deliberate. <strong>OpenCode</strong> for fast, model-agnostic pair programming in the terminal. <strong>Codex</strong> for parallel execution across isolated sandboxes. <strong>Claude Code</strong> for deep, codebase-wide planning and refactors. <strong>Hermes Agent</strong> — my own stack — routing models and orchestrating the other three. Different tools, different strengths, one workflow.</p><h2 id="the-core-loop" tabindex="-1">The core loop <a class="header-anchor" href="#the-core-loop" aria-label="Permalink to “The core loop”">​</a></h2>`,4),e(d,{items:[{title:`Brief the agents`},{title:`Generate & iterate`},{title:`Human review`},{title:`Deploy & monitor`}]}),o[1]||=n(`<p>The loop is exactly the four steps described in <a href="/Usf/en/about/how-i-work/">The Agentic Method</a>: brief, generate, review, deploy. What changes per tool is <em>where each step happens</em> — OpenCode lives in my terminal next to vim, Codex fans work out into sandboxes, Claude Code plans before it touches a file, and Hermes coordinates long-running tasks and keeps everyone supplied with the right model.</p><h2 id="what-agents-changed-about-my-engineering" tabindex="-1">What agents changed about my engineering <a class="header-anchor" href="#what-agents-changed-about-my-engineering" aria-label="Permalink to “What agents changed about my engineering”">​</a></h2><ul><li><strong>Specs became a first-class artifact.</strong> A precise brief is worth more than a clever prompt.</li><li><strong>Review became a superpower.</strong> Reading diffs fast — and suspiciously — is now a core skill.</li><li><strong>Architecture matters more, not less.</strong> Agents amplify good structure and expose bad structure instantly.</li><li><strong>Testing got serious.</strong> If the test suite is weak, agents will happily produce confident garbage.</li></ul><div class="info custom-block"><p class="custom-block-title">Proof, not promises</p><p>This portfolio — two locales, a cloned VitePress theme, custom SVG icon set and 14 generated illustrations — was built through this loop. So were NetPilot, OmniRouter and every panel in the <a href="/Usf/en/projects/netpilot/">projects</a> section.</p></div><p>The following pages document each tool: <a href="/Usf/en/agentic/opencode/">OpenCode</a>, <a href="/Usf/en/agentic/codex/">Codex</a>, <a href="/Usf/en/agentic/claude-code/">Claude Code</a> and <a href="/Usf/en/agentic/hermes/">Hermes Agent</a>.</p>`,5)])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};